    const first = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
    const last = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

    expect(addUsage(addUsage(addUsage(undefined, first), undefined), last)).toEqual({
      inputTokens: 9,
      outputTokens: 5,
      totalTokens: 14,
    });
  });
});
